//! The Datadog attribute catalogue, compiled in and built once per process.
//!
//! `data/catalogs/datadog/attributes.toml` is generated by `scripts/engine/sync_datadog_catalog.py`
//! from Datadog's "Default Standard Attributes" table (DataDog/documentation, BSD-3-Clause): the
//! reserved attributes, searched by their bare name, and the standard attributes, searched as
//! `@<name>`, each with its type, group and products. Facts only: hover is written from them.
//!
//! A team's pipelines remap attributes, so the catalogue never makes a finding on its own: an
//! attribute it lacks is not reported (RFC §14). It serves hover and completion.

use std::collections::HashMap;
use std::sync::OnceLock;

pub use crate::catalog_model::Attribute;

/// The catalogue, indexed by name.
#[derive(Debug)]
pub struct Catalog {
    /// The reserved attributes, in the table's order.
    pub reserved: Vec<Attribute>,
    /// The standard attributes, in the table's order.
    pub attributes: Vec<Attribute>,
    reserved_by_name: HashMap<String, usize>,
    by_name: HashMap<String, usize>,
}

/// What `build.rs` stores (#1743), parsed once at build time: the reserved and the standard
/// attributes.
type Model = (Vec<Attribute>, Vec<Attribute>);

/// The catalogue, pre-parsed by `build.rs` and decoded on first use.
fn model() -> Model {
    opentide_dataset::compiled_value(
        "datadog-catalog",
        opentide_dataset::blob!("datadog-catalog"),
    )
}

impl Catalog {
    /// The catalogue, built on first use and shared by every thread (ADR 0013, §3).
    pub fn cached() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            let (reserved, attributes) = model();
            let index = |rows: &[Attribute]| {
                rows.iter()
                    .enumerate()
                    .map(|(i, a)| (a.name.clone(), i))
                    .collect::<HashMap<_, _>>()
            };
            Catalog {
                reserved_by_name: index(&reserved),
                by_name: index(&attributes),
                reserved,
                attributes,
            }
        })
    }

    /// The standard attribute at `path` (without `@`), compared case-sensitively, as Datadog
    /// compares attribute names.
    #[must_use]
    pub fn attribute(&self, path: &str) -> Option<&Attribute> {
        self.by_name.get(path).map(|&i| &self.attributes[i])
    }

    /// The reserved attribute named `name` (`host`, `service`).
    #[must_use]
    pub fn reserved(&self, name: &str) -> Option<&Attribute> {
        self.reserved_by_name.get(name).map(|&i| &self.reserved[i])
    }
}

/// The hover text of an attribute: what the catalogue states, nothing more.
pub(crate) fn markdown(attribute: &Attribute, reserved: bool) -> String {
    let name = if reserved {
        attribute.name.clone()
    } else {
        format!("@{}", attribute.name)
    };
    let kind = if reserved {
        "Datadog reserved attribute"
    } else {
        "Datadog standard attribute"
    };
    let products = attribute
        .products
        .iter()
        .map(|p| match p.as_str() {
            "logs" => "Logs",
            "apm" => "APM",
            "rum" => "RUM",
            other => other,
        })
        .collect::<Vec<_>>()
        .join(", ");
    let mut out = format!("**{name}** ({}): {kind}", attribute.ty);
    if !reserved {
        out.push_str(&format!(", {}", attribute.domain));
    }
    if !products.is_empty() {
        out.push_str(&format!(". Set by {products}"));
    }
    out.push('.');
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cached_loads_the_expected_rows() {
        let catalog = Catalog::cached();
        assert_eq!(catalog.reserved.len(), 9);
        assert_eq!(catalog.attributes.len(), 199);
        assert!(catalog.reserved("host").is_some());
        assert!(catalog.reserved("env").is_some());
        let ip = catalog
            .attribute("network.client.ip")
            .expect("network.client.ip");
        assert_eq!(ip.ty, "string");
        assert!(catalog.attribute("evt.outcome").is_some());
        assert!(catalog.attribute("@evt.outcome").is_none());
        assert!(std::ptr::eq(catalog, Catalog::cached()));
    }

    #[test]
    fn hover_states_the_facts() {
        let catalog = Catalog::cached();
        let host = catalog.reserved("host").expect("host");
        assert_eq!(
            markdown(host, true),
            "**host** (string): Datadog reserved attribute. Set by Logs, APM."
        );
        let ip = catalog.attribute("network.client.ip").expect("ip");
        assert!(
            markdown(ip, false)
                .starts_with("**@network.client.ip** (string): Datadog standard attribute, ")
        );
    }
}
